(()=>{
'use strict';
const root=document.getElementById('black-hole-custom'),canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d',{alpha:false});
const get=id=>root.querySelector('#space-'+id);
const angle=get('angle'),starsToggle=get('stars'),galaxiesToggle=get('galaxies'),play=get('play'),style=get('style'),detail=get('detail'),status=get('status');
const source=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const background='#25303c';
const ramp=' .,:;irsXA253hMHGS#9B&@';
const W=640;
let H=400;
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches,visible=true,time=0,last=0,drawn=0,frames=0;
let cols=0,rows=0,starMap=[],galaxyMap=[],galaxyIndex=[];
function resizeScene(){
 const width=Math.max(1,innerWidth),height=Math.max(1,innerHeight);
 H=W*height/width;
 const pixelRatio=Math.min(window.devicePixelRatio||1,1.5);
 canvas.width=Math.round(width*pixelRatio);canvas.height=Math.round(height*pixelRatio);
 cols=0;
}
resizeScene();
if(innerWidth<600)detail.value='128';
let seed=73021;
function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}
const stars=Array.from({length:165},()=>({x:12+random()*(W-24),y:12+random()*376,phase:random()*Math.PI*2,rate:.45+random()*.7,power:.3+random()*.7,large:random()>.86,tint:random()}));
const galaxies=[{x:86,y:74,sx:45,sy:21,angle:-.45,tint:0},{x:554,y:321,sx:45,sy:24,angle:.65,tint:1},{x:96,y:337,sx:26,sy:13,angle:.3,tint:2}];
function cache(){
 const n=+detail.value;if(n===cols)return;cols=n;rows=Math.round(cols*H/W/1.44);
 starMap=new Int16Array(cols*rows).fill(-1);galaxyMap=new Float32Array(cols*rows);galaxyIndex=new Int8Array(cols*rows).fill(-1);
 stars.forEach((s,i)=>{const x=Math.floor(s.x/W*cols),y=Math.min(rows-1,Math.floor(s.y/400*rows));starMap[y*cols+x]=i;});
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){
  const x=(col+.5)/cols*W,y=(row+.5)/rows*H,i=row*cols+col;
  galaxies.forEach((g,k)=>{
   const dx=x-g.x,dy=y-g.y/400*H,ca=Math.cos(g.angle),sa=Math.sin(g.angle);
   const gx=(dx*ca+dy*sa)/g.sx,gy=(-dx*sa+dy*ca)/g.sy,r=Math.hypot(gx,gy);
   if(r>1.45)return;
   const theta=Math.atan2(gy,gx),arm=Math.pow((Math.cos(2*(theta-3.8*Math.log(r+.15)))+1)*.5,6);
   const grain=.8+.2*Math.sin(col*4.12+row*7.73+k);
   const value=(.88*Math.exp(-r*6.8)+.48*arm*Math.exp(-r*1.95)+.045*Math.exp(-r*3))*grain;
   if(value>galaxyMap[i]){galaxyMap[i]=value;galaxyIndex[i]=k;}
  });
 }
}
function restore(){
 let s;
 try{s=JSON.parse(localStorage.getItem('cyl-ascii-intro')||'null');}catch{}
 if(s){
  if(['tiles','ascii'].includes(s.rendering))style.value=s.rendering;
  if([128,176,240].includes(s.detail))detail.value=String(s.detail);
  if(Number.isFinite(s.angle))angle.value=String(clamp(s.angle,-180,180));
  if(typeof s.stars==='boolean')starsToggle.checked=s.stars;
  if(typeof s.galaxies==='boolean')galaxiesToggle.checked=s.galaxies;
 }
 labels();draw();
}
function labels(){
 get('angle-value').textContent=angle.value+'°';
 play.textContent=paused?'Play animation':'Pause animation';
 play.setAttribute('aria-pressed',String(paused));
 document.documentElement.style.setProperty('--space-bg',background);
 const bg=[1,3,5].map(i=>parseInt(background.slice(i,i+2),16));
 document.documentElement.dataset.tone=(bg[0]*.2126+bg[1]*.7152+bg[2]*.0722)>145?'light':'dark';
}
function save(){
 try{localStorage.setItem('cyl-ascii-intro',JSON.stringify({angle:+angle.value,stars:starsToggle.checked,galaxies:galaxiesToggle.checked,rendering:style.value,detail:+detail.value}));}catch{}
}
function mix(bg,target,a){return `rgb(${Math.round(bg[0]+(target[0]-bg[0])*a)},${Math.round(bg[1]+(target[1]-bg[1])*a)},${Math.round(bg[2]+(target[2]-bg[2])*a)})`;}
function draw(){
 cache();const cw=canvas.width/cols,ch=canvas.height/rows,tiles=style.value==='tiles';
 const bg=[1,3,5].map(i=>parseInt(background.slice(i,i+2),16));
 const light=(bg[0]*.2126+bg[1]*.7152+bg[2]*.0722)>145;
 ctx.fillStyle=background;ctx.fillRect(0,0,canvas.width,canvas.height);
 ctx.font=`500 ${ch*.86}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';
 const rotation=+angle.value*Math.PI/180,ca=Math.cos(rotation),sa=Math.sin(rotation);
 // Fill the viewport with upright ASCII; compose the black hole away from the introduction.
 const portrait=H/W>1.1;
 const centerX=W*(portrait?.55:.60),centerY=H*(portrait?.28:.38);
 const scale=Math.min(W*(portrait?1.2:1.1)/(2*(Math.abs(ca)*267.5+Math.abs(sa)*127.5)),H*(portrait?.40:.72)/(2*(Math.abs(sa)*267.5+Math.abs(ca)*127.5)));
 const paleStar=light?[35,42,62]:[216,229,255],warmStar=light?[74,45,28]:[255,222,175];
 const galaxyTints=light?[[60,48,93],[86,48,64],[33,63,79]]:[[185,177,255],[246,185,216],[162,218,244]];
 for(let row=0;row<rows;row++)for(let col=0;col<cols;col++){
  const i=row*cols+col,px=col*cw,py=row*ch,vx=(col+.5)/cols*W-centerX,vy=(row+.5)/rows*H-centerY;
  const dx=(ca*vx+sa*vy)/scale,dy=(-sa*vx+ca*vy)/scale,x=dx+267.5,y=dy+127.5;
  const radius=Math.hypot(dx,dy),inside=radius<53;
  // A black event horizon occludes the distant sky even on a pale custom background.
  if(inside){ctx.fillStyle='#000000';ctx.fillRect(px,py,cw+1,ch+1);}
  else{
   if(galaxiesToggle.checked&&galaxyIndex[i]>=0){
    const k=galaxyIndex[i],shine=.82+.11*Math.sin(time*.43+k*2)+.07*Math.sin(time*.83+k);
    const v=galaxyMap[i]*shine;
    if(v>.023){
     if(tiles){ctx.fillStyle=mix(bg,galaxyTints[k],Math.min(.3,v*.45));ctx.fillRect(px,py,cw-.65,ch-.65);}
     ctx.fillStyle=mix(bg,galaxyTints[k],Math.min(1,.12+v*1.55));
     const glyph=' .,:;*oO@'[clamp(Math.floor(v*12),1,8)];ctx.fillText(glyph,px+cw*.5,py+ch*.5,cw*.96);
    }
   }
   if(starsToggle.checked&&starMap[i]>=0){
    const s=stars[starMap[i]],shine=s.power*(.35+.65*(.5+.5*Math.sin(time*s.rate+s.phase)));
    ctx.fillStyle=mix(bg,s.tint>.72?warmStar:paleStar,.18+shine*.8);
    ctx.fillText(s.large?(shine>.64?'*':'+'):(shine>.65?':':'.'),px+cw*.5,py+ch*.5,cw*.96);
   }
  }
  if(x<0||x>511||y<0||y>233)continue;
  const theta=Math.atan2(dy,dx),band=Math.exp(-(((dy-4)/7)**2));
  const flowAngle=theta+(1-band)*(.018*Math.sin(theta*5-time*1.2)+.012*Math.sin(theta*13+time*.7));
  let sx=267.5+radius*Math.cos(flowAngle),sy=127.5+radius*Math.sin(flowAngle);
  sx=sx*(1-band)+(x+6*Math.sin(time*.3)+2*Math.sin(x*.03-time))*band;
  sy=sy*(1-band)+(y+.65*Math.sin(x*.02-time*1.5))*band;
  const texture=(.96+.14*Math.sin(18*theta-1.5*time+radius*.22)+.08*Math.sin(31*theta-2.7*time-radius*.51))*(1-band)+(.99+.16*Math.sin(x*.16+time*2.3)+.08*Math.sin(x*.37+time*3.7))*band;
  const p=(clamp(Math.round(sy),0,233)*512+clamp(Math.round(sx),0,511))*3;
  const r=clamp((source[p]-3)*texture,0,255),g=clamp((source[p+1]-3)*texture,0,255),b=clamp((source[p+2]-3)*texture,0,255);
  if((radius<50&&Math.abs(dy-4)>4)||(r+g+b)<15)continue;
  const lum=(r*.2126+g*.7152+b*.0722)/255;
  const glyph=band>.65&&lum>.55?'=':ramp[clamp(Math.floor(lum*(ramp.length-1)),1,ramp.length-1)];
  const localBg=inside?[0,0,0]:bg;
  if(light&&!inside){
   if(tiles){ctx.fillStyle=mix(bg,[78,48,42],lum*.45);ctx.fillRect(px,py,cw-.65,ch-.65);}
   ctx.fillStyle=mix(bg,[58,30,25],Math.min(1,.13+lum*.9));
  }else{
   if(tiles){ctx.fillStyle=`rgb(${Math.round(localBg[0]+(255-localBg[0])*r/255*.52)},${Math.round(localBg[1]+(255-localBg[1])*g/255*.52)},${Math.round(localBg[2]+(255-localBg[2])*b/255*.52)})`;ctx.fillRect(px,py,cw-.65,ch-.65);}
   ctx.fillStyle=`rgb(${Math.round(localBg[0]+(255-localBg[0])*clamp((r*1.18+6)/255,0,1))},${Math.round(localBg[1]+(255-localBg[1])*clamp((g*1.18+6)/255,0,1))},${Math.round(localBg[2]+(255-localBg[2])*clamp((b*1.18+6)/255,0,1))})`;
  }
  ctx.fillText(glyph,px+cw*.5,py+ch*.5,cw*.96);
 }
 canvas.dataset.frames=String(++frames);canvas.dataset.time=time.toFixed(3);
}
let raf=0;
function schedule(){if(!raf&&!paused&&visible&&!document.hidden)raf=requestAnimationFrame(tick);}
function tick(now){
 raf=0;
 if(paused||!visible||document.hidden){last=0;return;}
 if(!last)last=now;
 time+=Math.min(.06,(now-last)/1000);last=now;
 if(now-drawn>48){drawn=now;draw();}
 schedule();
}
play.addEventListener('click',()=>{paused=!paused;last=0;labels();status.textContent=paused?'Animation paused':'Animation playing';schedule();});
for(const el of [angle]){el.addEventListener('input',()=>{labels();draw();});el.addEventListener('change',save);}
for(const el of [style,detail,starsToggle,galaxiesToggle])el.addEventListener('change',()=>{draw();save();});
new IntersectionObserver(e=>{visible=e[0].isIntersecting;last=0;schedule();}).observe(canvas);
document.addEventListener('visibilitychange',()=>{last=0;schedule();});
motionPreference.addEventListener('change',e=>{paused=e.matches;last=0;labels();schedule();});
window.addEventListener('resize',()=>{resizeScene();draw();});
restore();schedule();
})();
